# Generates m_prism_lib.mere: the prism library as mere-ruby ships it, turned
# into Mere string literals so that `require "prism"` needs no file on the
# load path.
#
#   . ./tools/ref_ruby.sh && ruby tools/gen_prism_lib.rb > m_prism_lib.mere
#
# Two halves, as in the reference:
#
# - The Ruby half: the reference's lib/prism.rb and lib/prism/**/*.rb
#   (Prism 1.8.2 as Ruby 4.0.9 installs it; the node classes, the
#   deserializer and the visitors are generated by Ruby's build from
#   prism/templates, so they are read from the INSTALLED rubylibdir, not from
#   a source tree), byte for byte. Prism is MIT (vendor/prism/LICENSE.md).
#   lib/prism/ffi.rb is left out: it is the backend for a ruby with the ffi
#   gem, and prism.rb never reaches it here (RUBY_ENGINE is "ruby").
# - The C half: prism/extension.c is a C extension mere-ruby cannot load. Its
#   replacement is lib/prism_ext.rb in this repository, written by hand in
#   Ruby over the five libprism externs (tools/prism_glue.c), and answered
#   under the name prism.rb requires it by, "prism/prism".
#
# ⚠ Each file is ONE chain of literals inside the function, as json's are,
#   and nothing is a top-level `let`: the compiler folds a chain of literals
#   into one (node.rb's 20,000 lines fold in 1.5 s), while every top-level
#   `let` nests the rest of the program one level deeper in the emitted C --
#   150 of them took the bracket depth from 488 to 1017, past what the build
#   passes to clang (tools/bracket_depth_check.sh).
#
# The source directory is the reference's rubylibdir unless given.
require "rbconfig"
dir = ARGV[0] || RbConfig::CONFIG["rubylibdir"]
here = File.expand_path("..", __dir__)
files = [["prism/prism", "#{here}/lib/prism_ext.rb"]]
names = ["prism"] + Dir.glob("#{dir}/prism/**/*.rb").sort.map { |f| f.delete_prefix("#{dir}/").delete_suffix(".rb") }
names.delete("prism/ffi")
names.each { |n| files << [n, "#{dir}/#{n}.rb"] }

def lit(line)
  line.gsub(/[\\"{}\t\r]/) { |c| { "\\" => "\\\\", '"' => '\\"', "{" => "\\{", "}" => "\\}", "\t" => "\\t", "\r" => "\\r" }[c] }
end

version = File.read("#{dir}/prism.rb")[/VERSION\s*=\s*"([^"]+)"/, 1] || "1.8.2"
puts "// GENERATED by tools/gen_prism_lib.rb from the reference's lib/prism*"
puts "// (Prism #{version}) and lib/prism_ext.rb -- do not edit. Answered by"
puts "// prism_lib_src, which do_require asks after syslog_lib_src."
puts ""
puts "let prism_lib_src = fn (name: str) ->"
puts "  let n = (if ends_with_rb name then substring name 0 (str_len name - 3) else name) in"
files.each_with_index do |(n, path), i|
  puts "  #{i == 0 ? "if" : "else if"} str_eq n \"#{n}\" then"
  File.read(path).lines.each_with_index do |l, j|
    body = l.chomp
    nl = l.end_with?("\n") ? "\\n" : ""
    sep = j == 0 ? "    " : "    ++ "
    puts "#{sep}\"#{lit(body)}#{nl}\""
  end
end
puts "  else \"\";"
